package com.rohit.inventory.service;
import com.rohit.inventory.entity.*; import com.rohit.inventory.repository.*; import java.util.*; import java.math.BigDecimal; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AlertService { private final AlertRepository alerts; private final NotificationService notifications; private final WarehouseRepository warehouses; private final ProductRepository products; public AlertService(AlertRepository alerts,NotificationService notifications,WarehouseRepository warehouses,ProductRepository products){this.alerts=alerts;this.notifications=notifications;this.warehouses=warehouses;this.products=products;} @Transactional public void evaluate(UUID warehouseId,UUID productId,BigDecimal available){Warehouse w=warehouses.findById(warehouseId).orElse(null);Product p=products.findById(productId).orElse(null);if(w==null||p==null)return;String type=available.signum()==0?"OUT_OF_STOCK":p.getMaximumStock().signum()>0&&available.compareTo(p.getMaximumStock())>0?"OVERSTOCK":available.compareTo(p.getReorderLevel())<=0?"LOW_STOCK":null;if(type==null){alerts.findByAlertTypeAndWarehouseIdAndProductIdAndStatusIn("LOW_STOCK",warehouseId,productId,List.of("ACTIVE","ACKNOWLEDGED")).ifPresent(a->{a.setStatus("RESOLVED");a.setResolvedAt(java.time.Instant.now());});return;}if(alerts.findByAlertTypeAndWarehouseIdAndProductIdAndStatusIn(type,warehouseId,productId,List.of("ACTIVE","ACKNOWLEDGED")).isPresent())return;Alert a=new Alert();a.setAlertType(type);a.setSeverity(type.equals("OUT_OF_STOCK")?Alert.Severity.CRITICAL:Alert.Severity.WARNING);a.setWarehouse(w);a.setProduct(p);a.setTitle(type.replace('_',' '));a.setMessage(p.getName()+" stock requires attention at "+w.getName()+".");alerts.save(a);notifications.create(type,type.equals("OUT_OF_STOCK")?Notification.Severity.CRITICAL:Notification.Severity.WARNING,a.getTitle(),a.getMessage(),warehouseId,productId,"INVENTORY",null);} }
